extends SceneTree
# A5: calibrates tests/normal_map_check.gd on the Poly Haven _nor_gl / _nor_dx pair of the same
# material (CHANGE-BRIEF C2, Assignment 5 Step 3). Expected: the GL file low with directx=false and
# near 2 with directx=true; the DX file the other way round. Reversed results mean the sign
# convention is backwards (then flip s and say so in TEST-REPORT.md).
#   ./scripts/run-test.sh calibrate_normal_maps.gd 60
const Check = preload("res://tests/normal_map_check.gd")
const DIR := "res://art/textures/rusty_metal_sheet/"
const FILES := {"gl": "rusty_metal_sheet_nor_gl_1k.png", "dx": "rusty_metal_sheet_nor_dx_1k.png"}
const STRIDE := 4

func _initialize() -> void:
	var failures := 0
	var ratios := {}
	for key in FILES:
		var img := Image.load_from_file(ProjectSettings.globalize_path(DIR + FILES[key]))
		if img == null:
			print("FAIL load %s" % FILES[key])
			failures += 1
			continue
		var r_gl := Check.curl_ratio(img, false, STRIDE)
		var r_dx := Check.curl_ratio(img, true, STRIDE)
		ratios[key] = {"as_gl": r_gl, "as_dx": r_dx}
		print("%s file: %dx%d format=%d  curl_ratio directx=false: %.4f  directx=true: %.4f" % [key, img.get_width(), img.get_height(), img.get_format(), r_gl, r_dx])
	var ok_gl: bool = ratios.has("gl") and ratios.gl.as_gl < ratios.gl.as_dx
	var ok_dx: bool = ratios.has("dx") and ratios.dx.as_dx < ratios.dx.as_gl
	print("%s calibration: GL file reads as GL (%s), DX file reads as DX (%s)" % ["PASS" if ok_gl and ok_dx else "FAIL", ok_gl, ok_dx])
	if not (ok_gl and ok_dx):
		failures += 1
	print("NORMAL MAP CALIBRATION: %d failures (stride %d)" % [failures, STRIDE])
	quit(1 if failures else 0)

extends SceneTree
# A5 hint experiment capture (CHANGE-BRIEF Part B, TEST-REPORT "Hint experiment"). Needs a window:
#   ~/Downloads/Godot.app/Contents/MacOS/Godot --path godot --script res://tests/capture_hint.gd
# Loads scenes3d/hint_experiment.tscn, waits for frames to draw, saves the rendered viewport as PNG,
# and samples the centre of each of the three bands on each quad (the quad's local x = -1/3, 0, +1/3
# unprojected through the camera). Real engine output; judging it against the predictions is the
# human check. Prints one JSON line per quad.
var OUT: String = ProjectSettings.globalize_path("res://").path_join("../a5/evidence/captures/")
const BANDS := {"64": -1.0 / 3.0, "128": 0.0, "192": 1.0 / 3.0}

func _initialize() -> void:
	call_deferred("run")

func run() -> void:
	DirAccess.make_dir_recursive_absolute(OUT)
	var scene: Node3D = load("res://scenes3d/hint_experiment.tscn").instantiate()
	root.add_child(scene)
	for i in 10:
		await process_frame
	await RenderingServer.frame_post_draw
	await RenderingServer.frame_post_draw
	var img: Image = get_root().get_texture().get_image()
	var path := OUT.path_join("hint_experiment.png")
	img.save_png(path)
	var cam: Camera3D = scene.get_node("Camera3D")
	var env: Environment = scene.get_node("WorldEnvironment").environment
	print("image %dx%d tonemap_mode=%d exposure=%.1f file=%s" % [img.get_width(), img.get_height(), env.tonemap_mode, env.tonemap_exposure, path])
	for quad_name in ["QuadAsColor", "QuadAsData"]:
		var quad: MeshInstance3D = scene.get_node(quad_name)
		var mat: ShaderMaterial = quad.get_surface_override_material(0)
		var row := {"quad": quad_name, "use_color": mat.get_shader_parameter("use_color")}
		for band in BANDS:
			var world: Vector3 = quad.global_transform * Vector3(BANDS[band], 0.0, 0.0)
			var p: Vector2 = cam.unproject_position(world)
			var pi := Vector2i(int(floor(p.x)), int(floor(p.y)))
			var c := img.get_pixel(pi.x, pi.y)
			# the band is flat: also report the 5x5 min/max so a one-pixel error at a band edge shows
			var lo := 255; var hi := 0
			for dy in range(-2, 3):
				for dx in range(-2, 3):
					var n := img.get_pixel(pi.x + dx, pi.y + dy).r8
					lo = mini(lo, n); hi = maxi(hi, n)
			row["band_" + band] = {"window_px": [pi.x, pi.y], "rgb": [c.r8, c.g8, c.b8], "r_min_max_5x5": [lo, hi]}
		print(JSON.stringify(row))
	print("CAPTURE DONE")
	quit(0)

