extends SceneTree
# throwaway probe; deleted after use

func _initialize() -> void:
	call_deferred("run")

func dump_mesh(label: String, mi: MeshInstance3D) -> void:
	var mesh := mi.mesh
	print("%s: node=%s mesh=%s surfaces=%d" % [label, mi.get_path(), mesh, mesh.get_surface_count() if mesh else -1])
	if mesh:
		for i in mesh.get_surface_count():
			var m := mesh.surface_get_material(i)
			var name: String = mesh.get("surface_%d/name" % i) if mesh is ArrayMesh else ""
			var arr_name := (mesh as ArrayMesh).surface_get_name(i) if mesh is ArrayMesh else ""
			print("  surface %d name='%s' mat=%s path='%s' resname='%s' override=%s" % [i, arr_name, m, m.resource_path if m else "", m.resource_name if m else "", mi.get_surface_override_material(i)])
			print("    active=%s" % mi.get_active_material(i))
			if m is StandardMaterial3D:
				print("    albedo=%s" % (m as StandardMaterial3D).albedo_color)

func walk(n: Node, depth := 0) -> void:
	print("  ".repeat(depth) + "%s (%s)" % [n.name, n.get_class()])
	for c in n.get_children():
		walk(c, depth + 1)

func run() -> void:
	var scene: Node3D = load("res://scenes3d/props_room.tscn").instantiate()
	root.add_child(scene)
	walk(scene)
	for p in ["Hydrant", "HydrantRusty"]:
		var inst := scene.get_node(p)
		for c in inst.find_children("*", "MeshInstance3D", true, false):
			dump_mesh(p, c)
	var env: Environment = scene.get_node("WorldEnvironment").environment
	print("props env: bg_mode=%d bg=%s amb_src=%d amb=%s amb_e=%.2f tonemap=%d exposure=%.2f white=%.2f glow=%s fog=%s adj=%s ssao=%s ssr=%s ssil=%s sdfgi=%s" % [env.background_mode, env.background_color, env.ambient_light_source, env.ambient_light_color, env.ambient_light_energy, env.tonemap_mode, env.tonemap_exposure, env.tonemap_white, env.glow_enabled, env.fog_enabled, env.adjustment_enabled, env.ssao_enabled, env.ssr_enabled, env.ssil_enabled, env.sdfgi_enabled])
	var sun: DirectionalLight3D = scene.get_node("Sun")
	print("sun: energy=%.2f color=%s shadow=%s indirect=%.2f specular=%.2f dir=%s mode=%d" % [sun.light_energy, sun.light_color, sun.shadow_enabled, sun.light_indirect_energy, sun.light_specular, -sun.global_transform.basis.z, sun.directional_shadow_mode])
	var lights := scene.find_children("*", "Light3D", true, false)
	print("lights in props_room: %d" % lights.size())
	var hint: Node3D = load("res://scenes3d/hint_experiment.tscn").instantiate()
	root.add_child(hint)
	var henv: Environment = hint.get_node("WorldEnvironment").environment
	print("hint env: bg_mode=%d bg=%s amb_src=%d amb_e=%.2f tonemap=%d exposure=%.2f glow=%s fog=%s adj=%s" % [henv.background_mode, henv.background_color, henv.ambient_light_source, henv.ambient_light_energy, henv.tonemap_mode, henv.tonemap_exposure, henv.glow_enabled, henv.fog_enabled, henv.adjustment_enabled])
	print("hint lights: %d" % hint.find_children("*", "Light3D", true, false).size())
	for sp in ["res://shaders/hydrant_surface.gdshader", "res://shaders/hint_experiment.gdshader"]:
		var sh: Shader = load(sp)
		print(sp)
		for u in sh.get_shader_uniform_list():
			print("  ", u)
	for tp in ["res://art/textures/rusty_metal_sheet/rusty_metal_sheet_diff_1k.png", "res://art/textures/rusty_metal_sheet/rusty_metal_sheet_rough_1k.png", "res://art/textures/rusty_metal_sheet/rusty_metal_sheet_nor_gl_1k.png", "res://art/textures/rusty_metal_sheet/rusty_metal_sheet_nor_dx_1k.png", "res://art/hint/grey_3x1.png"]:
		var t: Texture2D = load(tp)
		var img := t.get_image()
		print("%s: %s %dx%d fmt=%d mip=%s" % [tp, t.get_class(), t.get_width(), t.get_height(), img.get_format() if img else -1, img.has_mipmaps() if img else null])
		var src := Image.load_from_file(ProjectSettings.globalize_path(tp))
		print("   source: %dx%d fmt=%d" % [src.get_width(), src.get_height(), src.get_format()])
	for mp in ["res://materials/hydrant_fresh.tres", "res://materials/hydrant_rusty.tres", "res://materials/hint_as_color.tres", "res://materials/hint_as_data.tres"]:
		var m: ShaderMaterial = load(mp)
		print(mp, " shader=", m.shader.resource_path, " props:")
		for p in m.get_property_list():
			if String(p.name).begins_with("shader_parameter/"):
				var v = m.get(p.name)
				print("   ", p.name, " = ", v.resource_path if v is Resource else v, " usage=", p.usage)
		print("   paint_tint get =", m.get_shader_parameter("paint_tint"), " uv_scale=", m.get_shader_parameter("uv_scale"))
	quit(0)

